"""Problem generators, the LM task (a harness `Task`) and the answer checker.

* **Generators** turn `(rng, count, params)` into `Problem`s. They live in a small registry, so a
  config's `{"type": "arithmetic", "params": {...}}` picks one; unknown params raise.
* **`build_problems`** runs every generator in a `TaskConfig`, assigns train/held-out splits
  (stratified by difficulty), removes duplicate questions across the whole set and returns the
  rows of `problems.jsonl` (see docs/lm_design.md, "Data contracts").
* **`LMTask`** wraps those rows. An LM episode is generated by the policy (token by token, inside
  `LocalLMPolicy`), not stepped through the task, so `initial_state` and `step` raise, and
  `verify` takes the decoded completion *text*.
* **The checker** reads the first integer in the completion and compares it with the answer.
"""
from __future__ import annotations

import re
from collections.abc import Callable, Collection, Hashable, Sequence
from dataclasses import dataclass
from pathlib import Path
from typing import Any, ClassVar, Protocol

import numpy as np

from capsplit.harness.interfaces import Prompt, Task
from capsplit.harness.lm.config import TaskConfig
from capsplit.harness.lm.storage import read_jsonl
from capsplit.harness.registry import TASKS

# --------------------------------------------------------------------------- Problems and generators


@dataclass(frozen=True)
class Problem:
    question: str
    answer: str  # an exact integer, as a string
    difficulty: str
    generator: str


class ProblemGenerator(Protocol):
    """Makes `count` distinct problems, none of whose questions is in `exclude`.

    `params` are the generator's config params; a key the generator does not know raises
    ValueError. All randomness comes from `rng`, so equal inputs give equal outputs.
    """

    def generate(
        self, rng: np.random.Generator, count: int, params: dict, exclude: Collection[str] = ...
    ) -> list[Problem]: ...


GENERATORS: dict[str, ProblemGenerator] = {}

# Extra fields copied into every problems.jsonl row a generator produces.
ROW_EXTRAS: dict[str, dict[str, Any]] = {}


def register_generator(name: str, **row_extra: Any) -> Callable[[type], type]:
    """Class decorator: `@register_generator("arithmetic")` registers an instance under `name`."""

    def decorate(cls: type) -> type:
        if name in GENERATORS and type(GENERATORS[name]) is not cls:
            raise ValueError(f"generator {name!r} is already registered to {type(GENERATORS[name]).__name__}")
        GENERATORS[name] = cls()
        ROW_EXTRAS[name] = dict(row_extra)
        return cls

    return decorate


def get_generator(name: str) -> ProblemGenerator:
    if name not in GENERATORS:
        raise KeyError(f"unknown problem generator {name!r}; registered: {', '.join(sorted(GENERATORS))}")
    return GENERATORS[name]


def _check_params(generator: str, params: dict, allowed: Collection[str], required: Collection[str] = ()) -> None:
    unknown = sorted(set(params) - set(allowed))
    if unknown:
        raise ValueError(f"{generator}: unknown params {unknown}; allowed params are {sorted(allowed)}")
    missing = sorted(set(required) - set(params))
    if missing:
        raise ValueError(f"{generator}: missing required params {missing}")


COMMUTATIVE = frozenset({"+", "*"})
_MAX_DRAWS = 1000  # draws per problem before a cell is declared exhausted


@register_generator("arithmetic")
class ArithmeticGenerator:
    """`a op b` with both operands exactly d digits (uniform on [10^(d-1), 10^d - 1]).

    Params: `digits` (list of operand digit counts, 1..18), `ops` (subset of "+", "-", "*"),
    `negative` (default False: for "-" the larger operand comes first, so answers are >= 0).
    Problem i goes to grid cell i mod (len(digits) * len(ops)), so every cell gets
    floor(count / cells) or one more problems. Difficulty is e.g. "d3_mul".
    """

    OPS: ClassVar[dict[str, str]] = {"+": "add", "-": "sub", "*": "mul"}

    def generate(
        self, rng: np.random.Generator, count: int, params: dict, exclude: Collection[str] = frozenset()
    ) -> list[Problem]:
        _check_params("arithmetic", params, ("digits", "ops", "negative"), required=("digits", "ops"))
        digits, ops = list(params["digits"]), list(params["ops"])
        negative = params.get("negative", False)
        if not digits or any(isinstance(d, bool) or not isinstance(d, int) or not 1 <= d <= 18 for d in digits):
            raise ValueError(f"arithmetic: digits must be a non-empty list of ints in 1..18, got {digits!r}")
        if not ops or any(op not in self.OPS for op in ops) or len(set(ops)) != len(ops):
            raise ValueError(f"arithmetic: ops must be a non-empty subset of {sorted(self.OPS)}, got {ops!r}")
        if not isinstance(negative, bool):
            raise TypeError(f"arithmetic: negative must be true or false, got {negative!r}")
        cells = [(d, op) for d in digits for op in ops]
        seen = set(exclude)
        out = []
        for i in range(count):
            d, op = cells[i % len(cells)]
            lo, hi = 10 ** (d - 1), 10**d - 1
            for _ in range(_MAX_DRAWS):
                a, b = (int(x) for x in rng.integers(lo, hi + 1, size=2))
                if op == "-" and not negative and a < b:
                    a, b = b, a
                question = f"{a} {op} {b}"
                # For + and *, "b op a" is the same problem: block both orders so the
                # train and held-out splits can never share a problem.
                twin = f"{b} {op} {a}" if op in COMMUTATIVE else question
                if question not in seen and twin not in seen:
                    break
            else:
                raise ValueError(f"arithmetic: cannot find a new distinct problem for d={d}, op={op!r}; ask for fewer")
            seen.add(question)
            if op in COMMUTATIVE:
                seen.add(f"{b} {op} {a}")
            answer = a + b if op == "+" else a - b if op == "-" else a * b
            out.append(Problem(question, str(answer), f"d{d}_{self.OPS[op]}", "arithmetic"))
        return out


@register_generator("gsm8k", possibly_contaminated=True)
class GSM8KGenerator:
    """Grade-school word problems from a local GSM8K jsonl (`{"question", "answer"}` rows; the
    answer ends with "#### N"). Nothing is downloaded: params `path` must name an existing file.
    Rows are drawn without replacement in an rng-chosen order. The model may have seen GSM8K in
    pre-training, so rows are tagged `possibly_contaminated`.
    """

    def generate(
        self, rng: np.random.Generator, count: int, params: dict, exclude: Collection[str] = frozenset()
    ) -> list[Problem]:
        _check_params("gsm8k", params, ("path",), required=("path",))
        path = Path(params["path"]).expanduser()
        if not path.is_file():
            raise FileNotFoundError(
                f"gsm8k: {path} does not exist. Download the GSM8K jsonl yourself (for example test.jsonl from "
                "github.com/openai/grade-school-math) and set params.path to it; nothing is downloaded automatically."
            )
        rows = list(read_jsonl(path))
        seen = set(exclude)
        out: list[Problem] = []
        for j in rng.permutation(len(rows)):
            if len(out) == count:
                break
            question = str(rows[j]["question"]).strip()
            if question in seen:
                continue
            seen.add(question)
            out.append(Problem(question, _gsm8k_answer(rows[j]["answer"], path, int(j)), "gsm8k", "gsm8k"))
        if len(out) < count:
            raise ValueError(f"gsm8k: {path} has only {len(out)} new distinct questions, {count} requested")
        return out


def _gsm8k_answer(text: str, path: Path, line: int) -> str:
    match = re.search(r"####\s*(-?[0-9][0-9,]*)\s*$", str(text))
    if match is None:
        raise ValueError(f"gsm8k: row {line} of {path} has no integer '#### N' answer")
    return str(int(match.group(1).replace(",", "")))


# --------------------------------------------------------------------------- Building problems.jsonl


def build_problems(task_config: TaskConfig) -> list[dict]:
    """Every generator's n_train + n_heldout problems as problems.jsonl rows, ids 0..P-1.

    Generator g uses rng seeded from SeedSequence([task.seed, g]) (one child stream to generate,
    one to split and order). Within each difficulty cell the train share is n_train / (n_train +
    n_heldout), rounded so the generator's totals are exact (largest remainder). A question
    already produced (by this or an earlier generator) is redrawn, so no question appears twice.
    """
    rows: list[dict] = []
    seen: set[str] = set()
    for g, gen_config in enumerate(task_config.generators):
        generator = get_generator(gen_config.type)
        n_train, n_heldout = gen_config.n_train, gen_config.n_heldout
        for name, value in (("n_train", n_train), ("n_heldout", n_heldout)):
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise ValueError(f"task.generators[{g}].{name} must be a non-negative integer, got {value!r}")
        gen_seq, split_seq = np.random.SeedSequence([task_config.seed, g]).spawn(2)
        problems = generator.generate(
            np.random.default_rng(gen_seq), n_train + n_heldout, dict(gen_config.params), exclude=seen
        )
        if len(problems) != n_train + n_heldout or len({p.question for p in problems} | seen) != len(seen) + len(
            problems
        ):
            raise RuntimeError(f"generator {gen_config.type!r} broke its contract (wrong count or repeated question)")
        seen.update(p.question for p in problems)
        split_rng = np.random.default_rng(split_seq)
        splits = _stratified_splits([p.difficulty for p in problems], n_train, split_rng)
        extra = ROW_EXTRAS.get(gen_config.type, {})
        for k in split_rng.permutation(len(problems)):
            p = problems[k]
            rows.append({
                "id": len(rows), "generator": p.generator, "question": p.question, "answer": p.answer,
                "split": splits[k], "difficulty": p.difficulty, **extra,
            })
    return rows


def _stratified_splits(difficulties: Sequence[str], n_train: int, rng: np.random.Generator) -> list[str]:
    """'train' or 'heldout' per item: each difficulty gets the same train share, totals exact."""
    total = len(difficulties)
    cells: dict[str, list[int]] = {}
    for i, d in enumerate(difficulties):
        cells.setdefault(d, []).append(i)
    names = list(cells)  # first-appearance order: deterministic tie-break
    ideal = [len(cells[c]) * n_train / total if total else 0.0 for c in names]
    quota = [int(x) for x in ideal]
    by_remainder = sorted(range(len(names)), key=lambda c: (-(ideal[c] - quota[c]), c))
    for c in by_remainder[: n_train - sum(quota)]:
        quota[c] += 1
    out = ["heldout"] * total
    for c, name in enumerate(names):
        for i in rng.permutation(cells[name])[: quota[c]]:
            out[int(i)] = "train"
    return out


# --------------------------------------------------------------------------- Checker

# Optional minus (ASCII or U+2212), then either comma-grouped digits ("1,234") or plain digits,
# then an optional decimal part (so "5.0" reads as 5 and "2.5" is recognised as not an integer).
_NUMBER = re.compile(r"[-−]?(?:[0-9]{1,3}(?:,[0-9]{3})+(?![0-9])|[0-9]+)(?:\.([0-9]+))?")


def first_integer(text: str) -> int | None:
    """The first number in `text` if it is an integer, else None.

    "The answer is 5" -> 5; "5 apples" -> 5; "-1,234" -> -1234; "x\\n42" -> 42; "3 then 4" -> 3;
    "5.0" -> 5; "five" -> None; "2.5" -> None (the first number is not an integer). An echoed
    question ("347 * 29 = 10063") reads as 347: the prompt asks for only the final number.
    """
    match = _NUMBER.search(text)
    if match is None:
        return None
    if match.group(1) is not None and match.group(1).strip("0"):
        return None
    whole = match.group(0).split(".")[0]
    return int(whole.replace(",", "").replace("−", "-"))


def check(text: str, answer: str) -> tuple[bool, bool]:
    """(valid, correct): valid iff the first number is an integer; correct iff it equals `answer`."""
    value = first_integer(text)
    return value is not None, value is not None and value == int(answer)


# --------------------------------------------------------------------------- Task


@TASKS.register("lm_arithmetic")
class LMTask(Task):
    """The harness `Task` for LM problems, built from problems.jsonl rows.

    `n_actions` and `horizon` are 0 and unused: the action space is the tokenizer's vocabulary
    and the horizon is `model.max_new_tokens`, both owned by the policy, not the task.
    """

    n_actions = 0
    horizon = 0

    def __init__(self, problems: Sequence[dict], prompt_template: str):
        rows = list(problems)
        ids = [row["id"] for row in rows]
        if ids != list(range(len(rows))):
            raise ValueError("problem ids must be 0..P-1 in order")
        self.rows = rows
        self.prompt_template = prompt_template
        self._prompts = tuple(
            Prompt(
                id=row["id"],
                tokens=(prompt_template.format(question=row["question"]),),
                tags={"split": row["split"], "generator": row["generator"], "difficulty": row["difficulty"]},
            )
            for row in rows
        )

    def prompts(self) -> Sequence[Prompt]:
        return self._prompts

    def answer(self, prompt_id: int) -> str:
        return str(self.rows[prompt_id]["answer"])

    def parse(self, prompt_id: int, text: str) -> tuple[bool, bool]:
        """(valid, correct) for a decoded completion; see `check`."""
        return check(text, self.answer(prompt_id))

    def verify(self, prompt_id: int, actions: Any) -> bool:
        """`actions` is the decoded completion text (a str), not token ids."""
        if not isinstance(actions, str):
            raise TypeError(f"LMTask.verify takes the completion text (str), got {type(actions).__name__}")
        return self.parse(prompt_id, actions)[1]

    def initial_state(self, prompt_id: int) -> Hashable:
        raise NotImplementedError("LM episodes are generated by the policy (LocalLMPolicy), not stepped by the task")

    def step(self, prompt_id: int, state: Hashable, action: int) -> tuple[Hashable, bool]:
        raise NotImplementedError("LM episodes are generated by the policy (LocalLMPolicy), not stepped by the task")

    def demonstrations(self, prompt_id: int) -> Sequence[Any]:
        """One demonstration: the answer string (the completion an SFT arm imitates)."""
        return (self.answer(prompt_id),)


def load_task(path: str | Path, prompt_template: str) -> LMTask:
    """An `LMTask` from a problems.jsonl file."""
    return LMTask(list(read_jsonl(Path(path))), prompt_template)


__all__ = [
    "GENERATORS", "ArithmeticGenerator", "GSM8KGenerator", "LMTask", "Problem", "ProblemGenerator",
    "build_problems", "check", "first_integer", "get_generator", "load_task", "register_generator",
]
